"""Keys generated by their holder in bounded-key FE (``bcfe/gc_ristretto255``, ``key_mode="h2"``; experimental).

The issuance of Sahai and Seyalioglu (SS10, Sec. 3.2: Pre, Auth, CheckAuth):

1. the key holder makes the secret keys of its slot itself and sends the
   authority ``w`` and their public keys (``holder.request``);
2. the authority checks its issuance policy, places the public keys by the
   bits of ``w``, derives the keys of the other positions from a fresh slot
   secret ``k`` and returns a grant (``kg.authorize``);
3. the key holder checks the slot of the grant (CheckAuth: its keys at the
   positions of ``w``, the other positions derived from ``k``) and only then
   takes the key (``holder.finish``).

The authority never sees the holder's secret keys, so it cannot decrypt the
holder's slot on its own; it still learns ``w``, which is in the request. It
keeps no copy of the key either: a lost key is not issued again.

Here a risk-scoring service gets a key for a linear score
``floor((w . x + bias) / 4)`` and decrypts the score of a client's features.
The notes of ``bcfe_credit_scoring.py`` apply as well: the key holder learns
its own ``w``, a new key does not open older ciphertexts, the requester id
must be one that the application authenticated, and the encryptor is
assumed honest.
"""

import os
import tempfile

import pyfe4ai
from pyfe4ai import circuits


def main() -> None:
    # the public circuit C(w, x) = floor((w . x + bias) / 4) for 3 features of 6 bits
    model = circuits.linear_score(n=3, bw=6, bx=6, shift=2)

    with tempfile.TemporaryDirectory() as state:
        # --- the key authority, issuing holder-generated keys
        kg, BCFE = pyfe4ai.create("bcfe/gc_ristretto255", circuit=model, key_mode="h2", max_keys=2, cache_dir=state)
        kg.setup()
        pp = kg.get_public_parameters()

        # --- 1. the key holder: its secret keys stay in `holder`; the request (w and the public keys) goes to
        # the authority only, since it holds w
        holder = BCFE.key_holder(pp)
        request = holder.request({"weights": [5, -3, 7], "bias": 20})

        # --- 2. the authority, for the requester id that the application authenticated; the grant holds k,
        # which reveals w (it tells which positions are derived): it goes to the key holder only
        grant = kg.authorize(request, requester="svc-risk-02", label="risk-v1")

        # --- 3. CheckAuth. A grant whose other positions are not derived from its k (say, an authority that
        # kept secret keys for them) is refused, and the request stays open:
        forged = dict(grant, k=os.urandom(16).hex())
        try:
            holder.finish(forged)
        except pyfe4ai.FEKeyError:
            print("CheckAuth: refused a grant whose other positions are not derived from its k")
        else:
            raise SystemExit("CheckAuth accepted a forged grant")
        key = holder.finish(grant)

        # --- a client encrypts its features under the public parameters that list the new slot, and the
        # key holder decrypts the score (and nothing else about x)
        pp = kg.get_public_parameters()
        ct = BCFE({"keys": {"pp": pp}}).encrypt({"x": [4, -2, 3]})
        print("risk score:", BCFE({"keys": {"pp": pp}}).decrypt(ct, key)["score"])


if __name__ == "__main__":
    main()
